import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper/modules";
import "swiper/css";

import img1 from "../../assets/17 New star.png";
import img2 from "../../assets/40 create party.png";
import img3 from "../../assets/46 click lock.png";
import img4 from "../../assets/14 gifting classic.png";
import img5 from "../../assets/11 live screen 1.png";
import img6 from "../../assets/10 Get started.png";
import img7 from "../../assets/34 Party event.png";
import img8 from "../../assets/81 expplore     all.png";
import img9 from "../../assets/live stream 2.png";
import img10 from "../../assets/stream feed 1.png";

const sliderData = [
  { img: img1, text: "Live Streaming Fun" },
  { img: img2, text: "Connect with Friends" },
  { img: img3, text: "Earn While You Stream" },
  { img: img4, text: "Join Interactive Games" },
  { img: img5, text: "Be Part of the Community" },
  { img: img6, text: "Win Exciting Rewards" },
  { img: img7, text: "Stream Anytime, Anywhere" },
  { img: img8, text: "Discover New Talents" },
  { img: img9, text: "Host Live Shows" },
  { img: img10, text: "Share Your Moments" },
];

export default function Front() {
  return (
    <section className="bg-black py-8">
      <Swiper
        modules={[Autoplay]}
        spaceBetween={40}
        slidesPerView={3}
        centeredSlides={true}
        loop={true}
        autoplay={{ delay: 3000, disableOnInteraction: false }}
        breakpoints={{
          320: { slidesPerView: 1 },
          768: { slidesPerView: 3 }
        }}
        className="slider-container"
      >
        {sliderData.map((slide, index) => (
          <SwiperSlide key={index}>
            <div className="slide-wrapper">
              {/* Image */}
              <img
                src={slide.img}
                alt={slide.text}
                className="slide-image"
              />

              {/* Text (only on active slide) */}
              <div className="slide-text">
                <h2>{slide.text}</h2>
              </div>
            </div>
          </SwiperSlide>
        ))}
      </Swiper>

      <style>{`
        /* Swiper container height to fit largest slide */
        .slider-container {
          height: 90vh;
        }

        /* Base slide style */
        .slide-wrapper {
          position: relative;
          width: 100%;
          height: 100%;
          border-radius: 24px;
          overflow: hidden;
          transition: all 0.6s ease;
        }

        /* Image always fits perfectly */
        .slide-image {
          inset: 0;
          width: 100%;
          height: 100vh;
          object-fit: cover;
          po
          transition: all 0.6s ease;
        }

        /* Dark blur effect for non-active slides */
        .swiper-slide {
          transition: all 0.6s ease;
          filter: blur(3px) brightness(0.5);
        }

        /* Smaller side slides */
        .swiper-slide-prev,
        .swiper-slide-next {
          transform: scale(0.7);
          height: 40vh !important;
          filter: blur(3px) brightness(0.5);
        }

        /* Active slide: big, clear */
        .swiper-slide-active {
          transform: scale(1);
          height: 90vh !important;
          filter: blur(0) brightness(1);
        }

        /* Far slides: very small */
        .swiper-slide:not(.swiper-slide-active):not(.swiper-slide-prev):not(.swiper-slide-next) {
          transform: scale(0.5);
          height: 30vh !important;
          filter: blur(5px) brightness(0.3);
        }

        /* Text style (only on active) */
        .slide-text {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 20px;
          text-align: center;
          opacity: 0;
          transition: opacity 0.6s ease;
        }

        .swiper-slide-active .slide-text {
          opacity: 1;
        }

        .slide-text h2 {
          color: white;
          font-size: clamp(1rem, 3vw, 2rem);
          font-weight: bold;
          text-shadow: 0 4px 20px rgba(0,0,0,0.8);
        }
      `}</style>
    </section>
  );
}
